import{_ as l,a0 as i,w as d,s as a,I as n,x as t,a1 as o,A as r,ao as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const g=JSON.parse('{"title":"Linux有问必答：如何在VPS上安装和访问CentOS 7远程桌面 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有问必答：如何在VPS上安装和访问CentOS 7远程桌面 | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有问必答：如何在VPS上安装和访问CentOS 7远程桌面 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有问必答：如何在VPS上安装和访问CentOS 7远程桌面 | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150323 Linux FAQs with Answers--How to install and access CentOS remote desktop on VPS","title":"Linux有问必答：如何在VPS上安装和访问CentOS 7远程桌面","tag":"201505","desc":""},"relativePath":"201505/20150323 Linux FAQs with Answers--How to install and access CentOS remote desktop on VPS.md","filePath":"[post].md"}'),m={name:"201505/20150323 Linux FAQs with Answers--How to install and access CentOS remote desktop on VPS.md"};function u(C,e,S,V,x,c){const s=i("Link");return d(),a("div",null,[e[21]||(e[21]=n("h1",{id:"linux有问必答-如何在vps上安装和访问centos-7远程桌面",tabindex:"-1"},[t("Linux有问必答：如何在VPS上安装和访问CentOS 7远程桌面 "),n("a",{class:"header-anchor",href:"#linux有问必答-如何在vps上安装和访问centos-7远程桌面","aria-label":"Permalink to “Linux有问必答：如何在VPS上安装和访问CentOS 7远程桌面”"},"​")],-1)),e[22]||(e[22]=n("blockquote",null,[n("p",null,[n("strong",null,"提问"),t(": 我想在VPS中安装CentOS桌面，并可以直接从我家远程访问GUI桌面。在VPS上设置和访问CentOS远程桌面有什么建议吗？")])],-1)),e[23]||(e[23]=n("p",null,"如何远程办公或者远程弹性化工作制在技术领域正变得越来越流行。这个趋势背后的一个技术就是远程桌面。你的桌面环境在云中，你可以在任何你去的地方，或者在家或者工作场所访问你的远程桌面。",-1)),e[24]||(e[24]=n("p",null,"这个教程介绍如何VPS中设置基于CentOS的远程桌面。现在，我们会先展示CentOS的基础环境。",-1)),n("p",null,[e[1]||(e[1]=t("我们假设你已经创建了CentOS 7的VPS实例（比如，使用",-1)),o(s,{href:"http://xmodulo.com/go/digitalocean"},{default:r(()=>[...e[0]||(e[0]=[t("DigitalOcean",-1)])]),_:1}),e[2]||(e[2]=t(" 或者 Amazon EC2）。请确保你的VPS实例有至少1GB的内存。不然，CentOS将会在你访问远程桌面的时候回崩溃。",-1))]),e[25]||(e[25]=n("h3",{id:"第一步-安装centos桌面",tabindex:"-1"},[t("第一步： 安装CentOS桌面 "),n("a",{class:"header-anchor",href:"#第一步-安装centos桌面","aria-label":"Permalink to “第一步： 安装CentOS桌面”"},"​")],-1)),n("p",null,[e[4]||(e[4]=t("如果你现在安装的CentOS版本是没有桌面的最小版本，你需要先在VPS上安装桌面（比如GNOME）。比如，DigitalOcean的镜像就是最小版本，它需要如下安装",-1)),o(s,{href:"http://xmodulo.com/how-to-install-gnome-desktop-on-centos.html"},{default:r(()=>[...e[3]||(e[3]=[t("桌面GUI",-1)])]),_:1})]),e[26]||(e[26]=p(`<pre><code># yum groupinstall &quot;GNOME Desktop&quot; 
</code></pre><p>在安装完成之后重启VPS。</p><h3 id="第二步-安装和配置vnc服务器" tabindex="-1">第二步：安装和配置VNC服务器 <a class="header-anchor" href="#第二步-安装和配置vnc服务器" aria-label="Permalink to “第二步：安装和配置VNC服务器”">​</a></h3><p>接下来就是安装和配置VNC服务器。我们使用的是TigerVNC,一个开源的VNC服务实现。</p><pre><code># yum install tigervnc-server 
</code></pre><p>现在创建一个用户账户（比如：xmodulo）用来访问远程桌面。</p><pre><code># useradd xmodulo
# passwd xmodulo 
</code></pre><p>当一个用户尝试使用VNC访问远程桌面时，VNC守护进程就会启动来处理这个请求。这意味着你需要为每个用户创建一个独立的VNC配置文件。</p><p>CentOS依靠systemd来管理和配置系统服务。所以我们将使用systemd来为用户xmodulo配置VNC服务器。</p><p>首先让我们使用下面任意一条命令来检查VNC服务器的状态。</p><pre><code># systemctl status vncserver@:.service
# systemctl is-enabled vncserver@.service 
</code></pre><p>默认的，刚安装的VNC服务并没有激活(禁用)。</p><p><img src="https://farm8.staticflickr.com/7613/16877514732_8ccffe7b6b_b.jpg" alt=""></p><p>现在复制一份通用的VNC服务文件来为用户xmodulo创建一个VNC服务配置。</p><pre><code># cp /lib/systemd/system/vncserver@.service /etc/systemd/system/vncserver@:1.service 
</code></pre><p>用本文编辑器来打开配置文件，用实际的用户名（比如：xmodulo）来替换[Service]下面的<code>&lt;USER&gt;</code>。同样。在ExecStart后面追加 <code>-geometry &lt;resolution&gt;</code> 参数。最后，要修改下面“ExecStart”和“PIDFile”两行。</p><pre><code># vi /etc/systemd/system/vncserver@:1.service 
</code></pre><hr><pre><code>[Service]
Type=forking
# Clean any existing files in /tmp/.X11-unix environment
ExecStartPre=/bin/sh -c &#39;/usr/bin/vncserver -kill %i &gt; /dev/null 2&gt;&amp;1 || :&#39;
ExecStart=/sbin/runuser -l xmodulo -c &quot;/usr/bin/vncserver %i -geometry 1024x768&quot;
PIDFile=/home/xmodulo/.vnc/%H%i.pid
ExecStop=/bin/sh -c &#39;/usr/bin/vncserver -kill %i &gt; /dev/null 2&gt;&amp;1 || :&#39;
</code></pre><p>现在为用户xmodulo设置密码（可选）。首先切换到该用户，并运行vncserver命令。</p><pre><code># su - xmodulo
# vncserver
</code></pre><p>你会被提示输入用户的VNC密码。密码设置完成后，你下次需要用这个密码来访问你的远程桌面。</p><p><img src="https://farm9.staticflickr.com/8752/16692564599_9c4e5da1b6_b.jpg" alt=""></p><p>最后，重新加载服务来使新的VNC配置生效：</p><pre><code># systemctl daemon-reload
</code></pre><p>在启动时自动启动VNC服务：</p><pre><code># systemctl enable vncserver@:1.service
</code></pre><p>检查vnc服务正在监听的端口：</p><pre><code># netstat -tulpn | grep vnc 
</code></pre><p><img src="https://farm8.staticflickr.com/7625/16692646729_7bb16c4897_b.jpg" alt=""></p><p>端口5901是VNC默认的客户端连接到VNC服务器使用的端口。</p><h3 id="第三步-通过ssh连接到远程桌面" tabindex="-1">第三步：通过SSH连接到远程桌面 <a class="header-anchor" href="#第三步-通过ssh连接到远程桌面" aria-label="Permalink to “第三步：通过SSH连接到远程桌面”">​</a></h3>`,32)),n("p",null,[e[6]||(e[6]=t("从设计上说，VNC使用的远程帧缓存（RFB）并不是一种安全的协议，那么在VNC客户端上直接连接到VNC服务器上并不是一个好主意。任何敏感信息比如密码都可以在VNC流量中被轻易地泄露。因此，我强烈建议使用SSH隧道来",-1)),o(s,{href:"http://xmodulo.com/how-to-set-up-vnc-over-ssh.html"},{default:r(()=>[...e[5]||(e[5]=[t("加密你的VNC流量",-1)])]),_:1}),e[7]||(e[7]=t("。",-1))]),e[27]||(e[27]=p(`<p>在你要运行VNC客户端的本机上，使用下面的命令来创建一个连接到远程VPS的SSH通道。当被要输入SSH密码时，输入用户的密码。</p><pre><code>$ ssh xmodulo@&lt;VPS-IP-address&gt; -L 5901:127.0.0.1:5901 
</code></pre><p>用你自己的VNC用户名来替换“xmodulo”，并填上你自己的VPS IP地址。</p><p>一旦SSH通道建立之后，远程VNC流量就会通过ssh通道路由并发送到127.0.0.1:5901。</p><p>现在启动你最爱的VNC客户端（比如：vinagre），来连接到127.0.0.1:5901。</p><p><img src="https://farm8.staticflickr.com/7639/16691289910_fae83510fb_o.png" alt=""></p><p>你将被要求输入VNC密码。当你输入VNC密码时，你就可以安全地连接到CentOS的远程桌面了。</p><p><img src="https://farm8.staticflickr.com/7614/16877678411_aa8349f6b1_c.jpg" alt=""></p><p><img src="https://farm9.staticflickr.com/8702/16256320434_81f9b5b70c_c.jpg" alt=""></p><hr>`,10)),n("p",null,[e[9]||(e[9]=t("via: ",-1)),o(s,{href:"http://ask.xmodulo.com/centos-remote-desktop-vps.html"},{default:r(()=>[...e[8]||(e[8]=[t("http://ask.xmodulo.com/centos-remote-desktop-vps.html",-1)])]),_:1})]),n("p",null,[e[13]||(e[13]=t("作者：",-1)),o(s,{href:"http://ask.xmodulo.com/author/nanni"},{default:r(()=>[...e[10]||(e[10]=[t("Dan Nanni",-1)])]),_:1}),e[14]||(e[14]=t(" 译者：",-1)),o(s,{href:"https://github.com/geekpi"},{default:r(()=>[...e[11]||(e[11]=[t("geekpi",-1)])]),_:1}),e[15]||(e[15]=t(" 校对：",-1)),o(s,{href:"https://github.com/wxy"},{default:r(()=>[...e[12]||(e[12]=[t("wxy",-1)])]),_:1})]),n("p",null,[e[18]||(e[18]=t("本文由 ",-1)),o(s,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[16]||(e[16]=[t("LCTT",-1)])]),_:1}),e[19]||(e[19]=t(" 原创翻译，",-1)),o(s,{href:"http://linux.cn/"},{default:r(()=>[...e[17]||(e[17]=[t("Linux中国",-1)])]),_:1}),e[20]||(e[20]=t(" 荣誉推出",-1))])])}const N=l(m,[["render",u]]);export{g as __pageData,N as default};
